    private final OrderId  id;         // never changes
    private       OrderStatus status;   // changes through lifecycle
    private       CustomerId customerId;
    private       Money      total;     // Value Object inside Entity

    // Business rules live here — not in a service
    public void cancel() {
        if (status == OrderStatus.SHIPPED)
            throw new DomainException("Cannot cancel a shipped order");
        this.status = OrderStatus.CANCELLED;
    }

    public boolean isComplete() {
        return status == OrderStatus.DELIVERED;
    }

    // Equality by ID — not by attributes
    @Override public boolean equals(Object o) {
        if (!(o instanceof Order other)) return false;
        return id.equals(other.id);
    }
}

