class Money {
private:
    double amount;
    string currency;

public:
    // Domain rule: money can't be negative
    Money(double amount, string currency) : amount(amount), currency(move(currency)) {
        if (amount < 0)
            throw invalid_argument("Money cannot be negative");
        if (this->currency.empty())
            throw invalid_argument("Currency required");
    }

    // Operations return new instances — immutable
    Money add(const Money& other) const {
        if (currency != other.currency)
            throw invalid_argument("Cannot add different currencies");
        return Money(amount + other.amount, currency);
    }

    Money multiply(int factor) const {
        return Money(amount * factor, currency);
    }

    bool isGreaterThan(const Money& other) const {
        return amount > other.amount;
    }
};

class EmailAddress {
private:
    string value;

public:
    EmailAddress(string value) : value(move(value)) {
        regex pattern("^[^@]+@[^@]+\\.[^@]+$");
        if (!regex_match(this->value, pattern))
            throw invalid_argument("Invalid email: " + this->value);
    }
};

