public class Order {  // Aggregate Root
    private final List<OrderItem> items = new ArrayList<>();
    private       Money total;

    // Only way to add an item — root controls and validates
    public void addItem(ProductId productId, int quantity, Money unitPrice) {
        if (status != OrderStatus.DRAFT)
            throw new DomainException("Cannot add items to a non-draft order");
        if (quantity <= 0)
            throw new DomainException("Quantity must be positive");

        items.add(new OrderItem(productId, quantity, unitPrice));
        recalculateTotal();   // keeps invariant: total = sum of items
    }

    // Invariant: total always equals sum of item prices
    private void recalculateTotal() {
        total = items.stream()
                     .map(i -> i.getUnitPrice().multiply(i.getQuantity()))
                     .reduce(Money.ZERO_INR, Money::add);
    }
}

