class Order {  // Aggregate Root
private:
    vector<OrderItem> items;
    Money total = Money::ZERO_INR;
    OrderStatus status;

public:
    // Only way to add an item — root controls and validates
    void addItem(ProductId productId, int quantity, Money unitPrice) {
        if (status != OrderStatus::DRAFT)
            throw runtime_error("Cannot add items to a non-draft order");
        if (quantity <= 0)
            throw runtime_error("Quantity must be positive");

        items.emplace_back(productId, quantity, unitPrice);
        recalculateTotal();   // keeps invariant: total = sum of items
    }

private:
    // Invariant: total always equals sum of item prices
    void recalculateTotal() {
        total = Money::ZERO_INR;
        for (const auto& item : items) {
            total = total.add(item.getUnitPrice().multiply(item.getQuantity()));
        }
    }
};

