public class PricingService {

    public Money calculateFinalPrice(Product product, Customer customer,
                                      PromoCode promoCode) {
        Money base = product.getBasePrice();

        // Domain rule: loyalty customers get 10% discount
        if (customer.isLoyaltyMember()) {
            base = base.multiply(0.90);
        }

        // Domain rule: promo codes apply after loyalty discount
        if (promoCode != null && promoCode.isValid()) {
            base = promoCode.apply(base);
        }

        return base;
    }
}

