class OrderPlaced : public DomainEvent {
public:
    const OrderId orderId;
    const CustomerId customerId;
    const Money total;
    const chrono::system_clock::time_point occurredAt;

    OrderPlaced(OrderId orderId, CustomerId customerId, Money total,
                chrono::system_clock::time_point occurredAt)
        : orderId(orderId), customerId(customerId), total(total), occurredAt(occurredAt) {}
};

// Aggregate fires the event when something significant happens
class Order {
private:
    vector<shared_ptr<DomainEvent>> events;

public:
    void place() {
        if (items.empty())
            throw runtime_error("Cannot place an empty order");
        status = OrderStatus::PLACED;
        events.push_back(make_shared<OrderPlaced>(id, customerId, total, chrono::system_clock::now()));
    }

    vector<shared_ptr<DomainEvent>> pullEvents() {
        vector<shared_ptr<DomainEvent>> result = events;
        events.clear();
        return result;
    }
};

