// Repository interface — lives in the domain layer
class OrderRepository {
public:
    virtual void save(const Order& order) = 0;
    virtual optional<Order> findById(const OrderId& id) = 0;
    virtual vector<Order> findByCustomer(const CustomerId& customerId) = 0;
    virtual void deleteById(const OrderId& id) = 0;
    virtual ~OrderRepository() = default;
};

// Implementation — lives in the infrastructure layer (hides DB details)
class JpaOrderRepository : public OrderRepository {
private:
    OrderJpaRepository jpaRepo;  // ORM-backed repository

public:
    void save(const Order& order) override {
        OrderEntity entity = OrderMapper::toEntity(order);  // map domain → DB
        jpaRepo.save(entity);
    }

    optional<Order> findById(const OrderId& id) override {
        auto entity = jpaRepo.findById(id.value());
        if (!entity.has_value()) return nullopt;
        return OrderMapper::toDomain(entity.value());  // map DB → domain
    }

    vector<Order> findByCustomer(const CustomerId& customerId) override {
        return jpaRepo.findAllByCustomerId(customerId.value());
    }

    void deleteById(const OrderId& id) override {
        jpaRepo.deleteById(id.value());
    }
};

